PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?pos ?emotionLabel (COUNT(DISTINCT ?dialectLemma) AS ?dialectWordCount)
WHERE {
  ?italianLemma a lila:Lemma ;
                dcterms:isPartOf <http://liita.it/data/id/lemma/LemmaBank> ;
                ontolex:writtenRep ?italianWord ;
                lila:hasPOS ?pos .

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  {
    ?italianSicilianLexEntry ontolex:canonicalForm ?italianLemma .
    ?italianSicilianLexEntry vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?dialectLemma .
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                  ontolex:writtenRep ?dialectWord .
  }
  UNION
  {
    ?italianParmigianoLexEntry ontolex:canonicalForm ?italianLemma .
    ?italianParmigianoLexEntry vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ontolex:canonicalForm ?dialectLemma .
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                  ontolex:writtenRep ?dialectWord .
  }
}
GROUP BY ?pos ?emotionLabel
ORDER BY DESC(?dialectWordCount) ?pos ?emotionLabel

